import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { CalendarDays, Copy, Percent, Plus, Search, Tag, Ticket, Trash2, TrendingUp, Pencil } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Badge, EmptyState, Modal, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Promotion } from '../lib/mock';

const emptyPromo = (): Promotion => ({
  id: `pr${Date.now()}`,
  code: '',
  type: 'percentage',
  value: 10,
  minOrder: 100000,
  validUntil: '2025-06-30',
  uses: 0,
  maxUses: 500,
  active: true,
});

export const Promotions = () => {
  const { t } = useTranslation();
  const { promotions, savePromotion, deletePromotion, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Promotion | null>(null);
  const [draft, setDraft] = useState<Promotion>(emptyPromo());
  const [toDelete, setToDelete] = useState<Promotion | null>(null);

  const filtered = useMemo(
    () => promotions.filter((p) => p.code.toLowerCase().includes(query.toLowerCase())),
    [promotions, query],
  );

  const activeCount = promotions.filter((p) => p.active).length;
  const totalUses = promotions.reduce((s, p) => s + p.uses, 0);

  const openCreate = () => {
    setEditing(null);
    setDraft(emptyPromo());
    setModalOpen(true);
  };

  const openEdit = (p: Promotion) => {
    setEditing(p);
    setDraft({ ...p });
    setModalOpen(true);
  };

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.code.trim()) {
      notify('Promo-kodni kiriting', 'error');
      return;
    }
    savePromotion({ ...draft, code: draft.code.toUpperCase().replace(/\s/g, '') });
    notify(editing ? t('updated') : t('created'));
    setModalOpen(false);
  };

  const toggleActive = (p: Promotion) => {
    savePromotion({ ...p, active: !p.active });
    notify(p.active ? 'Promo-kod to\'xtatildi' : 'Promo-kod faollashtirildi');
  };

  const copyCode = async (code: string) => {
    try {
      await navigator.clipboard.writeText(code);
      notify(`${code} nusxalandi`, 'info');
    } catch {
      notify(code, 'info');
    }
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('promotionsTitle')}
        subtitle={t('promotionsSubtitle')}
        action={<button className="btn-primary btn-sm" onClick={openCreate}><Plus size={16} /> {t('addPromotion')}</button>}
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Jami promo-kodlar" value={String(promotions.length)} icon={<Ticket size={20} />} />
        <StatCard label={t('active')} value={String(activeCount)} icon={<Tag size={20} />} tone="sky" />
        <StatCard label={t('uses')} value={String(totalUses)} icon={<TrendingUp size={20} />} tone="violet" />
        <StatCard label="O'rtacha chegirma" value={`${Math.round(promotions.reduce((s, p) => s + p.value, 0) / Math.max(1, promotions.length))}%`} icon={<Percent size={20} />} tone="amber" />
      </div>

      <div className="card p-4 sm:p-5">
        <div className="relative mb-4 max-w-sm">
          <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
          <input className="input pl-10" placeholder="Promo-kod qidirish..." value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>

        {filtered.length === 0 ? (
          <EmptyState title={t('noData')} icon={<Tag size={24} />} />
        ) : (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
            {filtered.map((p) => (
              <div key={p.id} className={cn('card relative overflow-hidden p-5 transition-all duration-300 hover:-translate-y-1', !p.active && 'opacity-60')}>
                <div className="absolute -right-6 -top-6 h-20 w-20 rounded-full bg-brand-500/10" />
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <button onClick={() => copyCode(p.code)} className="group flex items-center gap-2 font-display text-xl font-extrabold tracking-wide text-brand-700 dark:text-brand-300">
                      {p.code} <Copy size={14} className="text-[var(--muted)] opacity-0 transition group-hover:opacity-100" />
                    </button>
                    <p className="mt-1 text-xs font-semibold text-[var(--muted)]">
                      {p.type === 'percentage' ? `${p.value}% chegirma` : `${formatUZS(p.value)} chegirma`}
                    </p>
                  </div>
                  <Badge tone={p.active ? 'success' : 'neutral'}>{p.active ? t('active') : t('inactive')}</Badge>
                </div>

                <div className="mt-4 space-y-2 text-xs">
                  <div className="flex items-center justify-between">
                    <span className="text-[var(--muted)]">{t('minOrder')}</span>
                    <span className="font-bold">{p.minOrder ? formatUZS(p.minOrder) : 'Cheklanmagan'}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[var(--muted)]">{t('validUntil')}</span>
                    <span className="flex items-center gap-1 font-bold"><CalendarDays size={12} /> {p.validUntil}</span>
                  </div>
                </div>

                <div className="mt-4">
                  <div className="mb-1 flex justify-between text-[10px] font-bold text-[var(--muted)]">
                    <span>{t('uses')}</span><span>{p.uses} / {p.maxUses}</span>
                  </div>
                  <Progress value={(p.uses / p.maxUses) * 100} tone={p.uses >= p.maxUses ? 'rose' : 'brand'} />
                </div>

                <div className="mt-4 flex gap-1.5">
                  <button className="btn-secondary btn-sm flex-1" onClick={() => openEdit(p)}><Pencil size={12} /> {t('edit')}</button>
                  <button className="btn-secondary btn-sm flex-1" onClick={() => toggleActive(p)}>{p.active ? 'To\'xtatish' : 'Faollashtirish'}</button>
                  <button className="icon-btn h-8 w-8 text-rose-500" onClick={() => setToDelete(p)}><Trash2 size={13} /></button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? t('edit') : t('addPromotion')}>
        <form onSubmit={submit} className="space-y-4">
          <div>
            <label className="label">{t('code')}</label>
            <input className="input font-extrabold uppercase tracking-wider" value={draft.code} onChange={(e) => setDraft({ ...draft, code: e.target.value.toUpperCase() })} placeholder="MAX20" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="label">{t('type')}</label>
              <select className="select" value={draft.type} onChange={(e) => setDraft({ ...draft, type: e.target.value as Promotion['type'] })}>
                <option value="percentage">{t('percentage')} (%)</option>
                <option value="fixed">{t('fixed')} (so'm)</option>
              </select>
            </div>
            <div>
              <label className="label">{t('value')}</label>
              <input type="number" className="input" value={draft.value} onChange={(e) => setDraft({ ...draft, value: Number(e.target.value) })} />
            </div>
            <div>
              <label className="label">{t('minOrder')}</label>
              <input type="number" className="input" value={draft.minOrder} onChange={(e) => setDraft({ ...draft, minOrder: Number(e.target.value) })} />
            </div>
            <div>
              <label className="label">{t('validUntil')}</label>
              <input type="date" className="input" value={draft.validUntil} onChange={(e) => setDraft({ ...draft, validUntil: e.target.value })} />
            </div>
            <div>
              <label className="label">Maks. foydalanish</label>
              <input type="number" className="input" value={draft.maxUses} onChange={(e) => setDraft({ ...draft, maxUses: Number(e.target.value) })} />
            </div>
            <div>
              <label className="label">{t('status')}</label>
              <select className="select" value={draft.active ? 'active' : 'inactive'} onChange={(e) => setDraft({ ...draft, active: e.target.value === 'active' })}>
                <option value="active">{t('active')}</option>
                <option value="inactive">{t('inactive')}</option>
              </select>
            </div>
          </div>
          <div className="flex gap-2">
            <button type="button" className="btn-secondary flex-1" onClick={() => setModalOpen(false)}>{t('cancel')}</button>
            <button type="submit" className="btn-primary flex-1">{t('save')}</button>
          </div>
        </form>
      </Modal>

      <Modal open={!!toDelete} onClose={() => setToDelete(null)} title={t('delete')} subtitle={t('confirmDelete')}>
        <div className="rounded-2xl bg-rose-500/10 p-3 text-center font-display text-lg font-extrabold text-rose-500">{toDelete?.code}</div>
        <div className="mt-5 flex gap-2">
          <button className="btn-secondary flex-1" onClick={() => setToDelete(null)}>{t('cancel')}</button>
          <button
            className="btn flex-1 bg-rose-500 text-white hover:bg-rose-600"
            onClick={() => {
              if (toDelete) {
                deletePromotion(toDelete.id);
                notify(t('deleted'));
              }
              setToDelete(null);
            }}
          >
            {t('delete')}
          </button>
        </div>
      </Modal>
    </div>
  );
};
